 const cs=definitions.map((a,i)=>({id:`demo-${i+1}`,title:a[1],division:a[2],platform:a[3],format:a[4],status:a[5],date:prefix+String(a[0]).padStart(2,'0'),time:a[6],owner:a[7],caption:'Ide, cerita, dan inspirasi untuk tumbuh bersama. Yuk, mulai langkah berikutnya bersama Exata! #Exata #GrowTogether',url:''}));
 // Published examples in the same month for a realistic report, clearly marked as demo.
